-- ===========================================================================
-- Construction Portal — Migration 002: Full baseline schema (SUPABASE)
-- ===========================================================================
--
-- USE THIS FILE WHEN: you are setting up a FRESH Supabase project (or any
-- empty PostgreSQL database) and need the complete schema in one shot.
--
-- DO NOT run this against your existing local database — it already has this
-- schema. For the local database, run 001_upgrade_schema.sql instead.
--
-- This file was generated from the local database *after* 001 was applied and
-- verified, so it is the exact, complete schema — all 47 tables, every index,
-- constraint, sequence and trigger.
--
-- HOW TO RUN (Supabase)
--   1. Supabase Dashboard → SQL Editor → New query
--   2. Paste this entire file → Run
--   3. Then run 003_supabase_rls.sql   (row-level security — important)
--   4. Then run 004_seed_reference_data.sql
--
-- HOW TO RUN (psql)
--   psql "$SUPABASE_DATABASE_URL" -f 002_baseline_supabase.sql
--
-- NOTES
--   * pg_dump directives that only exist in PostgreSQL 18 (\restrict,
--     transaction_timeout) have been stripped so this runs on Supabase's
--     PostgreSQL 15/17.
--   * The `vector` extension is required by ai_conversations.embedding and
--     ai_insights.embedding. It is enabled below.
-- ===========================================================================

-- --- Extensions ------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- pgvector powers the embedding columns on ai_conversations and ai_insights.
--
-- It is treated as OPTIONAL here on purpose. Nothing in the application uses
-- those columns yet, and creating an extension needs privileges that a
-- managed platform may not grant — so a missing extension should not abort
-- the entire schema.
--
-- WITH SCHEMA public matters: Supabase installs extensions into an
-- `extensions` schema by default, and the column definitions below refer to
-- the type as public.vector. Pinning it to public keeps those consistent.
--
-- If this is skipped, the two embedding columns are simply not created. The
-- block at the end of this file adds them later once the extension exists.
DO $ext$
BEGIN
    CREATE EXTENSION IF NOT EXISTS "vector" WITH SCHEMA public;

    RAISE NOTICE 'pgvector enabled — AI embedding columns will be created.';
EXCEPTION
    WHEN insufficient_privilege OR undefined_file OR feature_not_supported THEN
        RAISE WARNING
            'pgvector unavailable (%). Continuing without the AI embedding columns; everything else is created normally. Enable it later (Supabase: Database -> Extensions -> vector) and re-run this file to add them.',
            SQLERRM;
END
$ext$;

SET search_path = public, extensions;


--
--

--
--

--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;

--
-- Name: validate_site_tender_company(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_site_tender_company() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  linked_tender_company integer;
BEGIN
  IF NEW.tender_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT tender.company_id
  INTO linked_tender_company
  FROM public.tenders AS tender
  WHERE tender.id = NEW.tender_id
    AND COALESCE(tender.is_deleted, false) = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'Tender % does not exist or has been deleted',
      NEW.tender_id;
  END IF;

  IF NEW.company_id IS DISTINCT FROM linked_tender_company THEN
    RAISE EXCEPTION
      'Site company_id (%) must match tender company_id (%)',
      NEW.company_id,
      linked_tender_company;
  END IF;

  RETURN NEW;
END;
$$;

SET default_tablespace = '';

SET default_table_access_method = heap;

