    CONSTRAINT tenders_priority_check CHECK (((priority)::text = ANY (ARRAY[('low'::character varying)::text, ('medium'::character varying)::text, ('high'::character varying)::text, ('critical'::character varying)::text]))),
    CONSTRAINT tenders_progress_percent_check CHECK (((progress_percent >= (0)::numeric) AND (progress_percent <= (100)::numeric))),
    CONSTRAINT tenders_risk_level_check CHECK (((risk_level)::text = ANY (ARRAY[('low'::character varying)::text, ('medium'::character varying)::text, ('high'::character varying)::text, ('critical'::character varying)::text])))
);

--
-- Name: tender_site_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tender_site_counts AS
 SELECT t.id AS tender_id,
    t.company_id,
    (count(s.id))::integer AS number_of_sites
   FROM (public.tenders t
     LEFT JOIN public.sites s ON (((s.tender_id = t.id) AND (COALESCE(s.is_deleted, false) = false))))
  WHERE (COALESCE(t.is_deleted, false) = false)
  GROUP BY t.id, t.company_id;

